from pathlib import Path
root = Path('outputs/20261012-orchestrator-routing-plan/checker-lane')
def edit(name, old, new):
    path = root / name
    text = path.read_text(encoding='utf-8')
    assert text.count(old) == 1, (name, old)
    path.write_text(text.replace(old, new), encoding='utf-8')
edit('allocation-interface.md', 'isolated original-byte/provenance and historical support validation.', 'isolated hash/size integrity, provenance-field syntax and historical supported-pair validation. Source-identity attestation requires separate independent Git-byte verification.')
